 11	/**
 12	 * 즉시 구매 요청 DTO
 13	 */
 14	@Data
 15	@Builder
 16	@AllArgsConstructor
 17	@NoArgsConstructor
 18	public class InstantOrderRequestDto {
 19	
 20	    @NotNull(message = "판매 입찰 ID는 필수입니다.")
 21	    private Long saleBidId;                 // 판매 입찰 ID
 22	
 23	    @NotNull(message = "배송지 ID는 필수입니다.")
 24	    private Long addressId;                 // 주소 ID
 25	
 26	    private boolean warehouseStorage;       // 창고 보관 여부
 27	
 28	    @NotNull(message = "결제 정보는 필수입니다.")
 29	    private PaymentRequestDto paymentRequest; // 결제 정보
 30	}     1	package com.fream.back.domain.order.service.command;
