186	    /**
187	     * 즉시 구매 OrderBid를 생성합니다.
188	     */
189	    private OrderBid createInstantOrderBid(Order order, SaleBid saleBid, Sale sale) {
190	        ProductSize productSize = saleBid.getProductSize();
191	
192	        OrderBid orderBid = OrderBid.builder()
193	                .user(order.getUser()) // 구매자
194	                .productSize(productSize)
195	                .bidPrice(saleBid.getBidPrice())
196	                .status(BidStatus.MATCHED) // 즉시 구매는 바로 매칭 상태
197	                .order(order) // Order와 매핑
198	                .sale(sale) // 셀러 정보 추가
199	                .build();
200	
201	        // 양방향 관계 설정
202	        orderBid.assignOrder(order);
203	
204	        // 플래그 설정 및 저장
205	        orderBid.markAsInstantPurchase();
206	        return orderBidRepository.save(orderBid);
207	    }
