  9	import org.springframework.stereotype.Service;
 10	
 11	import java.util.concurrent.CompletableFuture;
 12	
 13	/**
 14	 * 주문 처리 이벤트 발행 서비스
 15	 * 결제 + 배송 + 창고보관을 포함한 전체 주문 처리를 비동기로 처리
 16	 */
 17	@Service
 18	@RequiredArgsConstructor
 19	@Slf4j
 20	public class OrderEventProducer {
 21	
 22	    private final KafkaTemplate<String, OrderProcessingEvent> kafkaTemplate;
 23	
 24	    private static final String ORDER_PROCESSING_TOPIC = "order-processing-topic";
 25	    private static final String ORDER_RETRY_TOPIC = "order-retry-topic";
 26	
 27	    /**
 28	     * 주문 처리 이벤트 발행
 29	     *
 30	     * @param orderId 주문 ID
 31	     * @param userEmail 사용자 이메일
 32	     * @param requestDto 결제 및 배송 요청 정보
 33	     */
 34	    public void sendOrderProcessingEvent(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
 35	        try {
 36	            OrderProcessingEvent event = OrderProcessingEvent.create(orderId, userEmail, requestDto);
 37	
 38	            log.info("주문 처리 이벤트 발행 시작: 주문ID={}, 사용자={}, 이벤트ID={}",
 39	                    orderId, userEmail, event.getEventId());
 40	
 41	            // 주문 ID를 키로 사용하여 순서 보장
 42	            CompletableFuture<SendResult<String, OrderProcessingEvent>> future =
 43	                    kafkaTemplate.send(ORDER_PROCESSING_TOPIC, orderId.toString(), event);
 44	
 45	            future.whenComplete((result, ex) -> {
 46	                if (ex == null) {
 47	                    log.info("주문 처리 이벤트 발행 성공: 주문ID={}, 파티션={}, 오프셋={}",
 48	                            orderId,
 49	                            result.getRecordMetadata().partition(),
 50	                            result.getRecordMetadata().offset());
 51	                } else {
 52	                    log.error("주문 처리 이벤트 발행 실패: 주문ID={}, 오류={}", orderId, ex.getMessage(), ex);
 53	                }
 54	            });
 55	
 56	        } catch (Exception e) {
 57	            log.error("주문 처리 이벤트 발행 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
 58	            throw new RuntimeException("주문 처리 이벤트 발행 실패", e);
 59	        }
 60	    }
 61	
 62	    /**
 63	     * 주문 처리 재시도 이벤트 발행
 64	     */
 65	    public void sendOrderRetryEvent(OrderProcessingEvent originalEvent) {
 66	        try {
 67	            if (originalEvent.isMaxRetryExceeded()) {
 68	                log.warn("최대 재시도 횟수 초과로 재시도 중단: 주문ID={}, 재시도횟수={}",
 69	                        originalEvent.getOrderId(), originalEvent.getRetryCount());
 70	                return;
 71	            }
 72	
 73	            OrderProcessingEvent retryEvent = originalEvent.withRetry();
 74	
 75	            log.info("주문 처리 재시도 이벤트 발행: 주문ID={}, 재시도횟수={}",
 76	                    retryEvent.getOrderId(), retryEvent.getRetryCount());
 77	
 78	            CompletableFuture<SendResult<String, OrderProcessingEvent>> future =
 79	                    kafkaTemplate.send(ORDER_RETRY_TOPIC, retryEvent.getOrderId().toString(), retryEvent);
 80	
 81	            future.whenComplete((result, ex) -> {
 82	                if (ex == null) {
 83	                    log.info("주문 처리 재시도 이벤트 발행 성공: 주문ID={}", retryEvent.getOrderId());
 84	                } else {
 85	                    log.error("주문 처리 재시도 이벤트 발행 실패: 주문ID={}, 오류={}",
 86	                            retryEvent.getOrderId(), ex.getMessage(), ex);
 87	                }
 88	            });
 89	
 90	        } catch (Exception e) {
 91	            log.error("주문 처리 재시도 이벤트 발행 중 오류 발생: 주문ID={}, 오류={}",
 92	                    originalEvent.getOrderId(), e.getMessage(), e);
 93	        }
 94	    }
