 96	    /**
 97	     * 동기식 주문 처리 이벤트 발행 (테스트용)
 98	     */
 99	    public void sendOrderProcessingEventSync(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
100	        try {
101	            OrderProcessingEvent event = OrderProcessingEvent.create(orderId, userEmail, requestDto);
102	
103	            log.info("동기식 주문 처리 이벤트 발행: 주문ID={}", orderId);
104	
105	            SendResult<String, OrderProcessingEvent> result =
106	                    kafkaTemplate.send(ORDER_PROCESSING_TOPIC, orderId.toString(), event).get();
107	
108	            log.info("동기식 주문 처리 이벤트 발행 완료: 주문ID={}, 파티션={}, 오프셋={}",
109	                    orderId,
110	                    result.getRecordMetadata().partition(),
111	                    result.getRecordMetadata().offset());
112	
113	        } catch (Exception e) {
114	            log.error("동기식 주문 처리 이벤트 발행 실패: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
115	            throw new RuntimeException("동기식 주문 처리 이벤트 발행 실패", e);
116	        }
117	    }
