150	/**
151	 * 주문 처리 이벤트 컨슈머
152	 * 결제 + 배송 + 창고보관을 포함한 전체 주문 처리를 트랜잭션으로 처리
153	 */
154	@Service
155	@RequiredArgsConstructor
156	@Slf4j
157	public class OrderEventConsumer {
158	
159	    private final OrderRepository orderRepository;
160	    private final PaymentCommandService paymentCommandService;
161	    private final OrderShipmentCommandService orderShipmentCommandService;
162	    private final WarehouseStorageCommandService warehouseStorageCommandService;
163	    private final UserQueryService userQueryService;
164	    private final OrderEventProducer orderEventProducer;
165	    private final SimpMessagingTemplate messagingTemplate; // WebSocket 메시지 전송
166	    private final KafkaTemplate<String, Map<String, Object>> notificationKafkaTemplate;
167	
168	    /**
169	     * 주문 처리 이벤트 리스너
170	     * 전체 주문 처리를 하나의 트랜잭션으로 수행
171	     */
172	    @KafkaListener(
173	            topics = "order-processing-topic",
174	            groupId = "order-processing-group",
175	            containerFactory = "orderProcessingKafkaListenerContainerFactory"
176	    )
177	    @Transactional
178	    public void handleOrderProcessingEvent(
179	            @Payload OrderProcessingEvent event,
180	            Acknowledgment acknowledgment) {
181	
182	        Instant start = Instant.now();
183	
184	        try {
185	            log.info("주문 처리 이벤트 수신: 주문ID={}, 이벤트ID={}",
186	                    event.getOrderId(), event.getEventId());
187	
188	            // 1. 멱등성 검사 - 이미 처리된 주문인지 확인
189	            if (isOrderAlreadyProcessed(event.getOrderId())) {
190	                log.warn("이미 처리된 주문 요청 - 중복 처리 방지: 주문ID={}", event.getOrderId());
191	                acknowledgment.acknowledge();
192	                return;
193	            }
194	
195	            // 2. 주문 및 사용자 정보 조회
196	            Order order = orderRepository.findById(event.getOrderId())
197	                    .orElseThrow(() -> new IllegalArgumentException(
198	                            "주문을 찾을 수 없습니다. 주문ID: " + event.getOrderId()));
199	
200	            User user = userQueryService.findByEmail(event.getUserEmail());
201	
202	            // 3. 권한 확인
203	            if (!order.getUser().getId().equals(user.getId())) {
204	                log.error("주문과 사용자 정보 불일치: 주문ID={}, 주문사용자ID={}, 요청사용자ID={}",
205	                        event.getOrderId(), order.getUser().getId(), user.getId());
206	                throw new IllegalArgumentException("주문과 사용자 정보가 일치하지 않습니다.");
207	            }
208	
209	            // 4. 전체 주문 처리 수행 (하나의 트랜잭션)
210	            processCompleteOrder(order, user, event.getRequestDto());
211	
212	            // 5. 성공 알림 전송
213	            sendSuccessNotification(event.getOrderId(), event.getUserEmail());
214	
215	            // 6. 처리 완료 ACK
216	            acknowledgment.acknowledge();
217	
218	            // 처리 시간 로깅
219	            Instant end = Instant.now();
220	            Duration duration = Duration.between(start, end);
221	            log.info("주문 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
222	
223	        } catch (Exception e) {
224	            log.error("주문 처리 실패: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
225	            handleOrderProcessingFailure(event, e, acknowledgment);
226	        }
227	    }
228	
229	    /**
230	     * 주문 재시도 이벤트 리스너
231	     */
232	    @KafkaListener(
233	            topics = "order-retry-topic",
234	            groupId = "order-retry-group",
235	            containerFactory = "orderProcessingKafkaListenerContainerFactory"
236	    )
237	    @Transactional
238	    public void handleOrderRetryEvent(
239	            @Payload OrderProcessingEvent event,
240	            Acknowledgment acknowledgment) {
241	
242	        try {
243	            log.info("주문 재시도 처리: 주문ID={}, 재시도횟수={}",
244	                    event.getOrderId(), event.getRetryCount());
245	
246	            if (event.isMaxRetryExceeded()) {
247	                log.error("최대 재시도 횟수 초과: 주문ID={}, 재시도횟수={}",
248	                        event.getOrderId(), event.getRetryCount());
249	
250	                // 최종 실패 알림
251	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), "최대 재시도 횟수 초과");
252	                acknowledgment.acknowledge();
253	                return;
254	            }
255	
256	            // 멱등성 재확인
257	            if (isOrderAlreadyProcessed(event.getOrderId())) {
258	                log.info("재시도 중 주문 완료 확인: 주문ID={}", event.getOrderId());
259	                acknowledgment.acknowledge();
260	                return;
261	            }
262	
263	            // 재시도 지연 (백오프 전략)
264	            Thread.sleep(Math.min(1000 * event.getRetryCount(), 5000));
265	
266	            // 주문 재처리
267	            handleOrderProcessingEvent(event, acknowledgment);
268	
269	        } catch (InterruptedException e) {
270	            Thread.currentThread().interrupt();
271	            log.error("주문 재시도 중 인터럽트 발생: 주문ID={}", event.getOrderId());
272	            acknowledgment.acknowledge();
273	        } catch (Exception e) {
274	            log.error("주문 재시도 처리 중 오류: 주문ID={}, 오류={}",
275	                    event.getOrderId(), e.getMessage(), e);
276	            acknowledgment.acknowledge();
277	        }
278	    }
279	
280	    /**
281	     * 전체 주문 처리 수행 (하나의 트랜잭션)
282	     */
283	    private void processCompleteOrder(Order order, User user, PayAndShipmentRequestDto requestDto) {
284	        try {
285	            log.info("전체 주문 처리 시작: 주문ID={}", order.getId());
286	
287	            // 1. 결제 처리
288	            Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
289	            order.assignPayment(payment);
290	
291	            if (!payment.isSuccess()) {
292	                throw new RuntimeException("결제 실패: " + payment.getStatus());
293	            }
294	
295	            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());
296	
297	            // 2. 배송 정보 생성
298	            OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
299	                    order,
300	                    requestDto.getReceiverName(),
301	                    requestDto.getReceiverPhone(),
302	                    requestDto.getPostalCode(),
303	                    requestDto.getAddress()
304	            );
305	            order.assignOrderShipment(shipment);
306	            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());
307	
308	            // 3. 상태 업데이트 (OrderStatus enum 사용)
309	            if (!order.getStatus().canTransitionTo(OrderStatus.PAYMENT_COMPLETED)) {
310	                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
311	            }
312	            order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
313	
314	            if (requestDto.isWarehouseStorage()) {
315	                // 창고 보관일 경우
316	                WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
317	                order.assignWarehouseStorage(warehouseStorage);
318	
319	                // 상태 전환 검증
320	                if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
321	                    order.updateStatus(OrderStatus.PREPARING);
322	                }
323	                if (order.getStatus().canTransitionTo(OrderStatus.IN_WAREHOUSE)) {
324	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
325	                }
326	                if (order.getStatus().canTransitionTo(OrderStatus.COMPLETED)) {
327	                    order.updateStatus(OrderStatus.COMPLETED);
328	                }
329	
330	                log.info("창고 보관 처리 완료: 주문ID={}", order.getId());
331	            } else {
332	                // 실제 배송일 경우
333	                if (order.getStatus().canTransitionTo(OrderStatus.PREPARING)) {
334	                    order.updateStatus(OrderStatus.PREPARING);
335	                }
336	                log.info("배송 준비 완료: 주문ID={}", order.getId());
337	            }
338	
339	            // 4. 주문 저장
340	            orderRepository.save(order);
341	            log.info("전체 주문 처리 완료: 주문ID={}, 최종상태={}", order.getId(), order.getStatus());
342	
343	        } catch (Exception e) {
344	            log.error("전체 주문 처리 실패: 주문ID={}, 오류={}", order.getId(), e.getMessage(), e);
345	            throw e; // 트랜잭션 롤백을 위해 예외 재발생
346	        }
347	    }
348	
349	    /**
350	     * 주문이 이미 처리되었는지 확인 (멱등성 보장)
351	     */
352	    private boolean isOrderAlreadyProcessed(Long orderId) {
353	        try {
354	            Order order = orderRepository.findById(orderId).orElse(null);
355	            if (order == null) {
356	                return false;
357	            }
358	
359	            // PENDING_PAYMENT 상태가 아니면 이미 처리된 것으로 간주
360	            OrderStatus currentStatus = order.getStatus();
361	            return currentStatus != OrderStatus.PENDING_PAYMENT;
362	
363	        } catch (Exception e) {
364	            log.error("주문 중복 검사 중 오류 발생: 주문ID={}, 오류={}", orderId, e.getMessage(), e);
365	            return false;
366	        }
367	    }
368	
369	    /**
370	     * 주문 처리 실패 처리
371	     */
372	    private void handleOrderProcessingFailure(OrderProcessingEvent event, Exception error, Acknowledgment acknowledgment) {
373	        try {
374	            // 재시도 가능한 오류인지 판단
375	            if (isRetryableError(error)) {
376	                log.info("재시도 가능한 오류로 재시도 이벤트 발행: 주문ID={}", event.getOrderId());
377	                orderEventProducer.sendOrderRetryEvent(event);
378	            } else {
379	                log.error("재시도 불가능한 오류로 주문 처리 실패: 주문ID={}, 오류={}",
380	                        event.getOrderId(), error.getMessage());
381	                sendFailureNotification(event.getOrderId(), event.getUserEmail(), error.getMessage());
382	            }
383	
384	            acknowledgment.acknowledge();
385	
386	        } catch (Exception e) {
387	            log.error("주문 처리 실패 처리 중 오류: 주문ID={}, 오류={}", event.getOrderId(), e.getMessage(), e);
388	            acknowledgment.acknowledge();
389	        }
390	    }
391	
392	    /**
393	     * 재시도 가능한 오류인지 판단
394	     */
395	    private boolean isRetryableError(Exception error) {
396	        // 네트워크 오류, 일시적인 시스템 오류 등은 재시도 가능
397	        return !(error instanceof IllegalArgumentException) &&
398	                !(error.getMessage() != null && error.getMessage().contains("찾을 수 없습니다"));
399	    }
