401	    /**
402	     * 성공 알림 전송 (WebSocket + 선택적으로 Kafka)
403	     */
404	    private void sendSuccessNotification(Long orderId, String userEmail) {
405	        try {
406	            Map<String, Object> notification = new HashMap<>();
407	            notification.put("orderId", orderId);
408	            notification.put("userEmail", userEmail);
409	            notification.put("status", "SUCCESS");
410	            notification.put("type", "ORDER_COMPLETED");
411	            notification.put("title", "주문 완료");
412	            notification.put("message", "주문 및 결제가 성공적으로 완료되었습니다!");
413	            notification.put("timestamp", LocalDateTime.now());
414	
415	            // 1. 개별 사용자에게 WebSocket 알림 (추천 방식)
416	            String userDestination = "/user/" + userEmail + "/queue/notifications";
417	            messagingTemplate.convertAndSendToUser(userEmail, "/queue/notifications", notification);
418	
419	            // 2. 주문별 토픽으로 WebSocket 알림 (대안 방식)
420	            String orderDestination = "/topic/order/" + orderId;
421	            messagingTemplate.convertAndSend(orderDestination, notification);
422	
423	            log.info("주문 성공 WebSocket 알림 전송 완료: 주문ID={}, 사용자={}, 대상={}",
424	                    orderId, userEmail, userDestination);
425	
426	            // 3. 선택사항: 추가 알림 서비스로 Kafka 이벤트 발행
427	            try {
428	                Map<String, Object> kafkaNotification = new HashMap<>();
429	                kafkaNotification.put("type", "ORDER_COMPLETION");
430	                kafkaNotification.put("orderId", orderId);
431	                kafkaNotification.put("userEmail", userEmail);
432	                kafkaNotification.put("message", "주문이 완료되었습니다");
433	                kafkaNotification.put("timestamp", System.currentTimeMillis());
434	
435	                notificationKafkaTemplate.send("notification-topic", userEmail, kafkaNotification);
436	                log.debug("주문 완료 Kafka 알림 이벤트 발행: 주문ID={}", orderId);
437	
438	            } catch (Exception kafkaError) {
439	                log.warn("Kafka 알림 이벤트 발행 실패 (WebSocket 알림은 성공): 주문ID={}, 오류={}",
440	                        orderId, kafkaError.getMessage());
441	            }
442	
443	        } catch (Exception e) {
